             SUM(CASE WHEN SEX = 'F' THEN 1 ELSE 0 END) AS percentage_female_born_after_1930
FROM Patient;

SELECT 
    CAST(
        (SELECT COUNT(*) FROM Patient WHERE Diagnosis = 'SLE' AND Admission = '+') AS FLOAT
    ) / 
    NULLIF(
        (SELECT COUNT(*) FROM Patient WHERE Diagnosis = 'SLE' AND Admission = '-'), 0
    ) AS outpatient_to_inpatient_ratio;

SELECT 
    CAST(
        (SELECT COALESCE(SUM(b1.amount), 0)
         FROM budget b1
         JOIN event e1 ON b1.link_to_event = e1.event_id
         WHERE b1.category = 'Advertisement' AND e1.event_name = 'Yearly Kickoff'
        ) AS FLOAT
    ) /
    NULLIF(
        (SELECT COALESCE(SUM(b2.amount), 0)
         FROM budget b2
         JOIN event e2 ON b2.link_to_event = e2.event_id
         WHERE b2.category = 'Advertisement' AND e2.event_name = 'October Meeting'
        ), 0
    ) AS times_budget_more
